	}
	return state.Status
}

func activeBookmarkName(snapshot config.Snapshot) string {
	if snapshot.Runtime.ActiveBookmarkID == "" {
		return ""
	}
	for _, b := range snapshot.Bookmarks {
		if b.ID == snapshot.Runtime.ActiveBookmarkID {
			return b.Name
		}
